    clerkOfCourt: { label: "Ada County Clerk / Recorder", url: "https://adacounty.id.gov/" },
    propertyAppraiser: { label: "Ada County Assessor — Property Search", url: "https://adacounty.id.gov/" },
    survivingLiens: "Idaho tax deed is designed to convey free of most prior encumbrances except subsequent property taxes and certain special assessments — federal liens and title defects still require independent analysis. Sold as-is.",
    quietTitle: "Title insurers commonly require quiet title or extended seasoning after tax-deed purchase before insuring marketable title for resale/refinance.",
    gisMap: { label: "Ada County Assessor / GIS parcel resources", url: "https://adacounty.id.gov/" },
