    auctionPlatform: { label: "Bid4Assets — San Luis Obispo County", url: "https://www.bid4assets.com/SLO" },
    auctionFrequency: "Typically once yearly in May when inventory warrants (statutory minimum once every four years); re-offer possible in June",
    depositRules: "$5,000 deposit required for real-property auction participation. Winning bidder must pay in full by cashier's check, wire, or cash to SLO County Tax Collector within 72 hours after auction end or forfeit deposit and face ban from future sales. Timeshare auctions: no deposit but same 72-hour full payment. Register on bid4assets.com. Redemption Division (805) 781-5836.",
    taxCollector: { label: "San Luis Obispo County ACTTC — Public Auction of Tax-Defaulted Property", url: "https://www.slocounty.ca.gov/departments/auditor-controller-treasurer-tax-collector-public/tax-collector/services/public-auction-of-tax-defaulted-property", phone: "805-781-5836" },
