    gisMap: { label: "SLO County Land Use View (Planning & Building)", url: "https://gis.slocounty.ca.gov/Html5Viewer/Index.html?configBase=/Geocortex/Essentials/REST/sites/PL_LandUseView/viewers/PL_LandUseView/virtualdirectory/Resources/Config/Default" },
