    quietTitle: "Often used after a NM tax deed for insurable title, especially improved residential in Roswell.",
    gisMap: { label: "Chaves County Assessor EagleWeb / parcel resources", url: "https://eagleweb.chavescounty.gov/assessor/web/" },
