    auctionPlatform: { label: "Indiana County Tax Claim Bureau — Upset / Judicial / Repository", url: "https://www.indianacountypa.gov/departments/tax-claim/property-tax-auctions/", phone: "724-465-3810" },
    auctionFrequency: "Upset typically September annually; Judicial as scheduled for unsolds; Repository ongoing — confirm 2026 dates with Bureau",
